#!/usr/bin/env bash
# Bake plan 'cape': 24 chunks x 7 styles = 168 jobs at z10 (1024 px, native z12)
# Estimate: 140 min GPU, 3.4 GB on the share
# all-sea chunks skipped: 25 ['10/561/612', '10/561/613', '10/561/614', '10/561/615', '10/561/616', '10/561/617', '10/561/618', '10/562/612', '10/562/613', '10/562/614', '10/562/615', '10/562/616', '10/562/617', '10/562/618', '10/563/614', '10/563/615', '10/563/616', '10/563/617', '10/563/618', '10/564/617', '10/564/618', '10/565/617', '10/565/618', '10/566/618', '10/567/618']
# land hexes at H3 res 5: 73 (room for 24 players at 3 each)
set -euo pipefail
: "${ATLAS_HOST:?}" "${ATLAS_MAPS:?}" "${ATLAS_MODELS:?}"

# 0. The image at argus-atlas e3f2779, the commit of the docs Atlas publishes (once per host):
#   git clone https://github.com/smk762/argus-atlas.git argus-atlas-e3f2779 && cd argus-atlas-e3f2779 && \
#   git checkout e3f27791bc0b276428111a90dcbd2a95c01975b9 && docker build -t argus-atlas:e3f2779 --build-arg EXTRAS="server,cli,tiles" .
docker image inspect argus-atlas:e3f2779 >/dev/null 2>&1 || { echo 'build argus-atlas:e3f2779 first (step 0)'; exit 1; }
# Chunks of another argus-atlas build here would be seamed against: re-bake into a fresh ATLAS_MAPS.
foreign=$(grep -L e3f27791bc0b276428111a90dcbd2a95c01975b9 "$ATLAS_MAPS"/areas/cape/*/*/job.json 2>/dev/null || true)
[ -z "$foreign" ] || { echo "jobs from another argus-atlas build under $ATLAS_MAPS/areas/cape/:"; echo "$foreign" | head -3; exit 1; }
RUN="docker run --rm -u $(id -u):$(id -g) -w /tmp --add-host host.docker.internal:host-gateway -e COMFYUI_BASE_URL=http://host.docker.internal:8188 -e ATLAS_ALLOW_BAKE=1 -e ATLAS_RECIPES_DIR=/data/recipes -e ATLAS_MODELS_DIR=/data/models -e ATLAS_JOBS_DIR=/data/out/atlas -e ARGUS_GPU_COORDINATOR -e ARGUS_GPU_BROKER_URL -e ARGUS_GPU_BROKER_TOKEN -e ARGUS_GPU_BROKER_FALLBACK -e ARGUS_GPU_LEASE_TIMEOUT_S -e ATLAS_GPU_PRIORITY -e ARGUS_GPU_TENANT_MANIFEST=/app/gpu-tenant.yaml -v $ATLAS_HOST/dem:/data/dem -v $ATLAS_HOST/recipes:/data/recipes:ro -v $ATLAS_MODELS:/data/models:ro -v $ATLAS_MAPS:/data/out/atlas argus-atlas:e3f2779"

# 1. DEM: Copernicus GLO-30 for the block plus margins, one GeoTIFF (all-sea tiles are filled with 0 m)
[ -f "$ATLAS_HOST"/dem/cape_glo30.tif ] || \
  $RUN argus-atlas dem --bbox 17.8757,-34.9320,19.7414,-33.0907 --out /data/dem/cape_glo30.tif --allow-missing

# 2. OSM for the whole block in one Overpass call, and its place names (a separate extract: never a control)
[ -f "$ATLAS_HOST"/dem/osm/cape/osm.json ] || \
  $RUN argus-atlas osm --bbox 17.8857,-34.9220,19.7314,-33.1007 --zoom 12 --layers water,rivers,roads,forest,urban --out /data/dem/osm/cape
[ -f "$ATLAS_HOST"/dem/osm/cape-places/places.geojson ] || \
  $RUN argus-atlas osm --bbox 17.8857,-34.9220,19.7314,-33.1007 --zoom 12 --layers places --out /data/dem/osm/cape-places

# 3. Recipes: a missing <style>.json is copied from antique.json with its name and preset swapped
test -f "$ATLAS_HOST"/recipes/antique.json || { echo "missing $ATLAS_HOST/recipes/antique.json"; exit 1; }
test -f "$ATLAS_HOST"/recipes/tolkien.json || sed 's/"antique"/"tolkien"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/tolkien.json
test -f "$ATLAS_HOST"/recipes/imhof.json || sed 's/"antique"/"imhof"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/imhof.json
test -f "$ATLAS_HOST"/recipes/watercolor.json || sed 's/"antique"/"watercolor"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/watercolor.json
test -f "$ATLAS_HOST"/recipes/cyberpunk.json || sed 's/"antique"/"cyberpunk"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/cyberpunk.json
test -f "$ATLAS_HOST"/recipes/minecraft.json || sed 's/"antique"/"minecraft"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/minecraft.json
test -f "$ATLAS_HOST"/recipes/pixel.json || sed 's/"antique"/"pixel"/g' "$ATLAS_HOST"/recipes/antique.json > "$ATLAS_HOST"/recipes/pixel.json

# 4. Chunks, one style at a time, north to south, west to east. A re-run skips chunks that have tiles.
curl -sf -m 5 http://127.0.0.1:8188/system_stats >/dev/null || {
  [ "${ARGUS_GPU_COORDINATOR:-}" = broker ] && curl -sf -m 180 -X POST -H "Authorization: Bearer ${ARGUS_GPU_BROKER_TOKEN:-}" "${IRIS_URL:-http://127.0.0.1:8120}/services/comfyui/warm" >/dev/null; } || { echo 'ComfyUI is not answering on :8188'; exit 1; }
mkdir -p "$ATLAS_MAPS"/areas/cape/antique
[ -f "$ATLAS_MAPS"/areas/cape/antique/antique-10-563-612/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 10/563/612 --recipe antique --dem /data/dem/cape_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/cape/water.geojson --layer rivers=/data/dem/osm/cape/rivers.geojson --layer roads=/data/dem/osm/cape/roads.geojson --layer forest=/data/dem/osm/cape/forest.geojson --layer urban=/data/dem/osm/cape/urban.geojson --out /data/out/atlas/areas/cape/antique/antique-10-563-612
[ -f "$ATLAS_MAPS"/areas/cape/antique/antique-10-564-612/fantasy.pmtiles ] || \
  $RUN argus-atlas chunk --tile 10/564/612 --recipe antique --dem /data/dem/cape_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/cape/water.geojson --layer rivers=/data/dem/osm/cape/rivers.geojson --layer roads=/data/dem/osm/cape/roads.geojson --layer forest=/data/dem/osm/cape/forest.geojson --layer urban=/data/dem/osm/cape/urban.geojson --out /data/out/atlas/areas/cape/antique/antique-10-564-612
